INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('d8034578-806e-4828-8feb-70d17216ef08', 'COMPASS Pathways', 'compasspathways.com', 'http://compasspathways.com/', 'https://www.linkedin.com/company/compass-pathways/', 'https://app.dealroom.co/companies/compass_pathways', 'Psilocybin-based therapies for treatment-resistant mental health conditions', 'London', 'United Kingdom', 2016, 313, 37.2807, 393960002, 5, 0, 2025, 'operational', '[{"uuid":"0d9677ff-f669-4742-8e6f-d62df620f6e3","name":"George Goldsmith"},{"uuid":"c157cf3d-f2c5-4438-9770-aa3e50228832","name":"Ekaterina Malievskaia"}]', '{"uuid":"d8034578-806e-4828-8feb-70d17216ef08","type":"organization","domain":"compasspathways.com","name":"COMPASS Pathways","tagline":"Psilocybin-based therapies for treatment-resistant mental health conditions","about":"COMPASS Pathways is a publicly traded biotechnology company founded in 2016 by George Goldsmith, Ekaterina Malievskaia, and Lars Christian Wilde. The founders'' personal experience with a family mental health crisis highlighted the shortcomings of existing treatments and motivated them to establish the company. Headquartered in London, COMPASS is a key player in the psychedelic medicine industry, focusing on developing psilocybin-based therapies for patients with treatment-resistant depression (TRD). \n\nThe company''s primary drug candidate is COMP360, a proprietary, high-purity crystalline formulation of psilocybin administered in conjunction with psychological support from trained therapists. This model is currently undergoing a global Phase 3 clinical program, the largest of its kind for a psilocybin treatment. COMP360 has received \"Breakthrough Therapy\" designation from the U.S. Food and Drug Administration (FDA), which is intended to expedite the development of drugs for serious conditions. The company''s business model is centered on the clinical development, regulatory approval, and eventual commercialization of its therapies. Revenue is expected to be generated through future sales of approved treatments, licensing agreements, and partnerships. \n\nOriginally started as a non-profit, COMPASS transitioned to a for-profit entity to secure the substantial funding required for extensive clinical trials. This shift enabled the company to raise significant capital, including an $80 million Series B round in April 2020 and a successful IPO on the NASDAQ in September 2020, which raised $146.6 million. The company has attracted funding from notable investors such as Peter Thiel''s Founders Fund, ATAI Life Sciences, and McQuade Center for Strategic Research and Development. In March 2024, co-founders George Goldsmith and Ekaterina Malievskaia stepped down from the board of directors as a natural evolution of the company''s growth into a mature public entity focused on late-stage clinical development. \n\nKeywords: psilocybin therapy, treatment-resistant depression, COMP360, mental health care, biotechnology, clinical trials, psychedelic medicine, pharmaceutical, neuropsychiatric, drug development, innovative therapies, MDD, FDA, psychological support, anhedonia, SSRI, NASDAQ, CMPS, mental illness, evidence-based innovation","image":"storage.googleapis.com/dealroom-images-production/2026/10/27/a9441677ed09709e2440f49d11ceba41.png","dealroom_url":"https://app.dealroom.co/companies/compass_pathways","links":{"website":"http://compasspathways.com/","linkedin":"https://www.linkedin.com/company/compass-pathways/","twitter":"https://twitter.com/compasspathway","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/orga