l":393960002,"total_vc":393960002,"rounds_count":5},"valuation":{"value":1600000000,"year":2026,"month":11},"jobs":{"is_hiring":true,"open_count":95},"founders":{"total":2,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":null,"titles":["Executive Chairman","Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"George Goldsmith","type":"person","uuid":"0d9677ff-f669-4742-8e6f-d62df620f6e3","image":"storage.googleapis.com/dealroom-images-production/2026/07/28/59e257cd62481bf1f8e4f119669ac355.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/george_goldsmith","classifications":["super_founder"]}},{"raw_title":null,"titles":["CIO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"Ekaterina Malievskaia","type":"person","uuid":"c157cf3d-f2c5-4438-9770-aa3e50228832","image":"storage.googleapis.com/dealroom-images-production/2026/07/28/644a43f5d16ee3b32871ef3b916c5c2b.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/ekaterina_malievskaia","classifications":["serial_founder","super_founder"]}}]},"patents":{"count":38},"revenue":{"value":0,"year":2025},"traffic":{"monthly_visits":55000,"growth_3m":10},"available":["founders","patents","revenue","traffic"]}', '2026-11-05T15:17:12.433Z', 'COMPASS Pathways is a publicly traded biotechnology company founded in 2016 by George Goldsmith, Ekaterina Malievskaia, and Lars Christian Wilde. The founders'' personal experience with a family mental health crisis highlighted the shortcomings of existing treatments and motivated them to establish the company. Headquartered in London, COMPASS is a key player in the psychedelic medicine industry, focusing on developing psilocybin-based therapies for patients with treatment-resistant depression (TRD). 

The company''s primary drug candidate is COMP360, a proprietary, high-purity crystalline formulation of psilocybin administered in conjunction with psychological support from trained therapists. This model is currently undergoing a global Phase 3 clinical program, the largest of its kind for a psilocybin treatment. COMP360 has received "Breakthrough Therapy" designation from the U.S. Food and Drug Administration (FDA), which is intended to expedite the development of drugs for serious conditions. The company''s business model is centered on the clinical development, regulatory approval, and eventual commercialization of its therapies. Revenue is expected to be generated through future sales of approved treatments, licensing agreements, and partnerships. 

Originally started as a non-profit, COMPASS transitioned to a for-profit entity to secure the substantial funding required for extensive clinical trials. This shift enabled the company to raise significant capital, including an $80 million Series B round in April 2020 and a successful IPO on the NASDAQ in September 2020, which raised $146.6 million. The company has attracted funding from notable investors such as Peter Thiel''s Founders Fund, ATAI Life Sciences, and McQuade Center for Strategic Research and Development. In March 2024, co-founders George Goldsmith and Ekaterina Malievskaia stepped down from the board of directors as a natural evolution of the company''s growth into a mature public entity focused on late-stage clinical development. 

Keywords: psilocybin therapy, treatment-resistant depression, COMP360, mental health care, biotechnology, clinical trials, psychedelic medicine, pharmaceutical, neuropsychiatric, drug development, innovative therapies, MDD, FDA, psychological support, anhedonia, SSRI, NASDAQ, CMPS, mental illness, evidence-based innovation', '["help desk software","project management","customer relationship management","human resources","health platform","javascript frameworks","intelligence and analytics","customer experience management","recruitment marketing","javascript graphics","BioTechnology","corporate performance management","human resource management system","content management system","web analytics","network security","it infrastructure & operations management","database","healthcare marketing","testing and qa","it service management","certificates","Venture Capital","From $1B Exit to Zebra","Biotechnology","identity and access management","tag management","Public","DT and LS","widgets","b2b","communication and collaboration","e-commerce","ui frameworks","it infrastructure","Verified Unicorns and $1B Exits","advertising","sales","Pharmaceutical","uk is8 life sciences","security","Health Platform","api management","Late stage","Post IPO $1B","Psychedelic Drugs","marketing","photo galleries","issue trackers","javascript libraries","advanced analytics and data science","accounting and finance","customer service","development","appointment scheduling","applicant tracking systems","caching","office suites","programming languages","governance-risk and compliance","cloud infrastructure computing","frameworks and libraries","human capital management","affiliate advertising networks","hosting panels","Drug Development","human resource","payroll management and benefits administration","hris management","blogs","Sustainable Development Goals","Health","enterprise content management","b2c","education management","web hosting","team collaboration","Manufacturing","web and application servers","Angel","web platform extensions","science-based","Woman Founder","cache tools","Mental Health","web frameworks","miscellaneous","web servers","storage","data management","font scripts","wordpress plugins","social media marketing software","Commission","Biotech and Pharma","content delivery network","Good Health And Well-Being (#3)","Hard Tech","programming","analytics","Neurology","payroll processing","software framework","search engines"]', '["startup","unicorn","vc_backed","funded","exited"]', 94.57, 55000, 1, 95, 1600000000, -211999999, 2026, -298600000, 2026, '[{"year":2018,"revenue":null,"ebitda":-10516000,"profit":-13218999,"rnd":8916999,"valuation":150000000,"employees":null},{"year":2019,"revenue":null,"ebitda":-18386999,"profit":-19611999,"rnd":12563000,"valuation":150000000,"employees":null},{"year":2020,"revenue":null,"ebitda":-35446000,"profit":-60333999,"rnd":23366000,"valuation":544000000,"employees":null},{"year":2021,"revenue":null,"ebitda":-75563000,"profit":-71742000,"rnd":44027000,"valuation":544000000,"employees":135},{"year":2022,"revenue":0,"ebitda":-96800000,"profit":-91504999,"rnd":65052999,"valuation":544000000,"employees":210},{"year":2023,"revenue":0,"ebitda":-118924000,"profit":-118464000,"rnd":87518000,"valuation":559670000,"employees":218},{"year":2024,"revenue":0,"ebitda":-147783999,"profit":-155122000,"rnd":119038999,"valuation":283260000,"employees":246},{"year":2025,"revenue":0,"ebitda":-166512000,"profit":-287862000,"rnd":118435999,"valuation":641390000,"employees":228},{"year":2026,"revenue":0,"ebitda":-211999999,"profit":-298600000,"rnd":118435999,"valuation":1600000000,"employees":313}]', '2026-11-05T15:21:43.275Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('f27bfda4-b0f9-427c-a3c9-25ebad5ec60b', 'CellCentric', 'cellcentric.com', 'http://cellcentric.com', 'https://www.linkedin.com/company/cellcentric/', 'https://app.dealroom.co/companies/cellcentric', 'Oral p300/CBP inhibitor for targeted cancer therapy', 'Cambridge', 'United Kingdom', 2003, 68, 30.76923, 474088003, 20, 560958, 2021, 'operational', '[{"uuid":"da7a8284-e359-43cf-9df8-3a68c6dd781a","name":"Azim Surani"}]', '{"uuid":"f27bfda4-b0f9-427c-a3c9-25ebad5ec60b","type":"organization","domain":"cellcentric.com","name":"CellCentric","tagline":"Oral p300/CBP inhibitor for targeted cancer therapy","about":"CellCentric is a clinical-stage biotechnology company developing novel cancer therapies. It was spun out of the University of Cambridge in 2003 by Professor Azim Surani, a developmental biologist who sought to explore cell fate control mechanisms for new treatments. The company initially investigated over 50 different epigenetic-related targets before focusing on inhibiting the twin proteins p300 and CBP, which are key drivers of cancer progression.\n\nThe company''s lead product is Inobrodib (formerly CCS1477), a first-in-class, orally administered small molecule inhibitor of p300/CBP. Inobrodib is designed to disrupt the growth of cancer cells by impacting the expression of key cancer-driving genes like MYC and IRF4. A primary advantage of the drug is its oral capsule formulation, which allows for at-home administration, a significant preference for patients that can improve access and quality of life. CellCentric''s business model is centered on advancing Inobrodib through clinical trials to secure regulatory approval and eventual commercialization, either independently or through licensing deals. An earlier program was licensed to Takeda Pharmaceuticals. The company collaborates extensively with academic research groups and contract research organizations (CROs) to conduct its R&D.\n\nCellCentric is primarily targeting hematological malignancies and solid tumors. Its main focus is on relapsed and refractory multiple myeloma, a difficult-to-treat blood cancer where many patients eventually stop responding to existing therapies. Clinical trials have shown promising efficacy and a manageable safety profile for Inobrodib, particularly when used in combination with other standard-of-care drugs. The U.S. FDA has granted both Fast Track and Orphan Drug designations to Inobrodib for this indication. The company has secured significant funding to advance its clinical programs, including a $120 million Series C round in May 2025, with investors including RA Capital Management, Forbion, Pfizer, and BrightEdge, the venture arm of the American Cancer Society. These funds are earmarked for a pivotal Phase II/III study with the potential for accelerated approval and to support further combination trials.\n\nKeywords: p300/CBP inhibitor, oncology, Inobrodib, multiple myeloma, clinical-stage biotechnology, oral cancer drug, cell fate control, epigenetics, hematological malignancies, solid tumors, androgen receptor, relapsed refractory multiple myeloma, small molecule inhibitor, cancer research, drug development, transcription factors, biopharmaceutical, MYC, IRF4, anti-cancer therapy","image":"storage.googleapis.com/dealroom-images-production/2025/10/02/5b7bc79158ea2ad87b6fe0effceda047.png","dealroom_url":"https://app.dealroom.co/companies/cellcentric","links":{"website":"http://cellcentric.com","linkedin":"https://www.linkedin.com/company/cellcentric/","twitter":"https://twitter.com/cellcentric","instagram":null,"angellist":null,"crunchbase":"http://www.crunchbase.com/company/cellcentric"},"locations":[{"role":"hq","city":{"id":741,"name":"Cambridge"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":52.19099,"lon":0.121094},{"role":"founding","city":{"id":741,"name":"Cambridge"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":52.19099,"lon":0.121094}],"roles":[],"taxonomy":[{"id":114407,"name":"accelerator","type":"ownership"},{"id":23806,"name":"javascript frameworks","type":"techstack_category"},{"id":26706,"name":"intelligence and analytics","type":"techstack_category"},{"id":3004,"name":"BioTechnology","type":"sub_industry"},{"id":7206,"name":"continuous integration","type":"techstack_category"},{"id":51106,"name":"content management system","type":"techstack_category"},{"id":49406,"name":"web tools and plugins","type":"techstack_category"},{"id":48106,"name":"web analytics","type":"techstack_category"},{"id":30806,"name":"online form builders","type":"techstack_category"},{"id":23306,"name":"lead generation","type":"techstack_category"},{"id":49806,"name":"website builders","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":359001,"name":"Biotechnology","type":"sector"},{"id":2263701,"name":"Horizon Europe","type":"sector"},{"id":41806,"name":"tag management","type":"techstack_category"},{"id":2288701,"name":"DT and LS","type":"sector"},{"id":111,"name":"b2b","type":"client_focus"},{"id":6506,"name":"communication and collaboration","type":"techstack_category"},{"id":802,"name":"Augmented Reality","type":"technology"},{"id":1706,"name":"build automation","type":"techstack_category"},{"id":12406,"name":"e-commerce","type":"techstack_category"},{"id":43206,"name":"ui frameworks","type":"techstack_category"},{"id":51306,"name":"platform as a service","type":"te