ategory"},{"id":209,"name":"Commission","type":"income_stream"},{"id":2141701,"name":"Biotech and Pharma","type":"sector"},{"id":34806,"name":"programming","type":"techstack_category"},{"id":17006,"name":"analytics","type":"techstack_category"}],"launch_date":"2003-10","closing_date":null,"employees_count":68,"added_at":"2013-10-01T11:00:00.000Z","updated_at":"2026-11-05T01:05:55.351Z","subtype":"company","classifications":["startup","spinout","vc_backed","funded"],"employee_count_1y_growth":30.76923,"status":"operational","signal_rating":94.43,"unicorn_type":null,"became_unicorn_date":null,"became_thoroughbred_date":null,"exit_date":null,"investor":null,"funding":{"total":474088003,"total_vc":474088003,"rounds_count":20},"valuation":{"value":1320000000,"year":2026,"month":5},"jobs":{"is_hiring":true,"open_count":9},"founders":{"total":1,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2003","end_date":null,"person":{"name":"Azim Surani","type":"person","uuid":"da7a8284-e359-43cf-9df8-3a68c6dd781a","image":"storage.googleapis.com/dealroom-images-production/2024/12/24/8327415712ec127d823deab22f322883.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/azim_surani","classifications":["super_founder"]}}]},"patents":{"count":6},"revenue":{"value":560958,"year":2021},"traffic":{"monthly_visits":5200,"growth_3m":-13},"available":["founders","patents","revenue","traffic"]}', '2026-11-05T15:17:21.139Z', 'CellCentric is a clinical-stage biotechnology company developing novel cancer therapies. It was spun out of the University of Cambridge in 2003 by Professor Azim Surani, a developmental biologist who sought to explore cell fate control mechanisms for new treatments. The company initially investigated over 50 different epigenetic-related targets before focusing on inhibiting the twin proteins p300 and CBP, which are key drivers of cancer progression.

The company''s lead product is Inobrodib (formerly CCS1477), a first-in-class, orally administered small molecule inhibitor of p300/CBP. Inobrodib is designed to disrupt the growth of cancer cells by impacting the expression of key cancer-driving genes like MYC and IRF4. A primary advantage of the drug is its oral capsule formulation, which allows for at-home administration, a significant preference for patients that can improve access and quality of life. CellCentric''s business model is centered on advancing Inobrodib through clinical trials to secure regulatory approval and eventual commercialization, either independently or through licensing deals. An earlier program was licensed to Takeda Pharmaceuticals. The company collaborates extensively with academic research groups and contract research organizations (CROs) to conduct its R&D.

CellCentric is primarily targeting hematological malignancies and solid tumors. Its main focus is on relapsed and refractory multiple myeloma, a difficult-to-treat blood cancer where many patients eventually stop responding to existing therapies. Clinical trials have shown promising efficacy and a manageable safety profile for Inobrodib, particularly when used in combination with other standard-of-care drugs. The U.S. FDA has granted both Fast Track and Orphan Drug designations to Inobrodib for this indication. The company has secured significant funding to advance its clinical programs, including a $120 million Series C round in May 2025, with investors including RA Capital Management, Forbion, Pfizer, and BrightEdge, the venture arm of the American Cancer Society. These funds are earmarked for a pivotal Phase II/III study with the potential for accelerated approval and to support further combination trials.

Keywords: p300/CBP inhibitor, oncology, Inobrodib, multiple myeloma, clinical-stage biotechnology, oral cancer drug, cell fate control, epigenetics, hematological malignancies, solid tumors, androgen receptor, relapsed refractory multiple myeloma, small molecule inhibitor, cancer research, drug development, transcription factors, biopharmaceutical, MYC, IRF4, anti-cancer therapy', '["accelerator","javascript frameworks","intelligence and analytics","BioTechnology","continuous integration","content management system","web tools and plugins","web analytics","online form builders","lead generation","website builders","Venture Capital","Biotechnology","Horizon Europe","tag management","DT and LS","b2b","communication and collaboration","Augmented Reality","build automation","e-commerce","ui frameworks","platform as a service","it infrastructure","Pharmaceutical","uk is8 life sciences","Immersive Technologies","security","Oncology","Late stage","software development","javascript libraries","e-commerce platforms","Rumoured $1B","development","web fonts","office suites","programming languages","frameworks and libraries","performance","UKSU","Health","Manufacturing","web and application servers","rich text editors","Spinout","web platform extensions","science-based","consent management","email","miscellaneous","web servers","font scripts","wordpress plugins","shopping cart","Commission","Biotech and Pharma","programming","analytics"]', '["startup","spinout","vc_backed","funded"]', 94.43, 5200, 1, 9, 1320000000, -12262247, 2021, -16272155, 2024, '[{"year":2010,"revenue":1319999,"ebitda":-1055133,"profit":-810537,"rnd":null,"valuation":null,"employees":null},{"year":2011,"revenue":1319999,"ebitda":-1900150,"profit":-1630744,"rnd":null,"valuation":null,"employees":null},{"year":2012,"revenue":1319999,"ebitda":-2777135,"profit":-2341215,"rnd":null,"valuation":null,"employees":null},{"year":2013,"revenue":1319999,"ebitda":-1996258,"profit":-1831815,"rnd":null,"valuation":3405601