INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('6f985058-99f1-4118-9831-01a44a978c3b', 'Cleo', 'meetcleo.com', 'http://meetcleo.com', 'https://www.linkedin.com/company/cleo-ai/', 'https://app.dealroom.co/companies/cleo', 'AI financial assistant for budgeting and saving', 'London', 'United Kingdom', 2016, 733, 31.362007, 137605600, 6, 400000000, 2026, 'operational', '[{"uuid":"8a9ee26e-0b84-4e66-bc26-30cc9c418b77","name":"Barnaby Hussey-Yeo"}]', '{"uuid":"6f985058-99f1-4118-9831-01a44a978c3b","type":"organization","domain":"meetcleo.com","name":"Cleo","tagline":"AI financial assistant for budgeting and saving","about":"Cleo is an AI-powered financial assistant designed to help users, particularly Gen Z and millennials, manage their money through a conversational interface. The company was founded in 2016 by Barney Hussey-Yeo, a data scientist with a master''s degree in Machine Learning. Hussey-Yeo was motivated by his own struggles with money management and his experience at payday loan company Wonga, where he observed that customers were offered credit with little guidance on financial literacy. He began by creating scripts that would analyze his own banking and send him text alerts, an idea that evolved into Cleo. \n\nThe company launched through the Entrepreneurs First accelerator program, initially as a chatbot on Facebook Messenger in the UK. After seeing rapid user adoption, Cleo entered the U.S. market in 2018 and shifted its focus entirely to this region. The platform operates on a freemium business model. The free version offers basic features like spending analysis, budget tracking, and bill reminders through its AI chatbot. Cleo''s AI communicates with a distinct, often humorous and sassy personality, offering features like \"Roast Mode\" to critique spending habits and \"Hype Mode\" to praise financial progress. \n\nCleo generates revenue through tiered subscription plans that unlock advanced features. These premium tiers, such as Cleo Plus and Cleo Builder, provide services including interest-free cash advances up to $250, credit-building cards issued by WebBank, and enhanced financial insights. The Credit Builder Card is a secured card designed to help users establish or improve their credit scores. The company also earns interchange fees from transactions made with its card and fees from its cash advance service. Banking services are provided through a partnership with Thread Bank. \n\nCleo has raised a total of approximately $175 million in funding over several rounds, with a Series C round of $80 million in 2022 led by Sofina. Other key investors include Balderton Capital, EQT Ventures, and LocalGlobe. The company was last valued at $500 million in 2022 and has demonstrated significant revenue growth, nearing profitability. Headquartered in London, Cleo has grown to a team of over 300 employees and has attracted millions of users, primarily in the United States. \n\nKeywords: AI financial assistant, personal finance, budgeting app, money management, chatbot, spending tracker, credit builder, cash advance, savings goals, fintech, Gen Z finance, financial health, AI money coach, expense tracking, overdraft protection, financial education, subscription model, transaction analysis, automated savings, credit score improvement","image":"storage.googleapis.com/dealroom-images-production/2025/09/21/fd0e9d129a1d7d0cd153321e9eacf8a4.png","dealroom_url":"https://app.dealroom.co/companies/cleo","links":{"website":"http://meetcleo.com","linkedin":"https://www.linkedin.com/company/cleo-ai/","twitter":"https://twitter.com/meetcleo"