d":2240601,"name":"Woman Founder","type":"sector"},{"id":15106,"name":"email","type":"techstack_category"},{"id":30406,"name":"online community software","type":"techstack_category"},{"id":49006,"name":"web frameworks","type":"techstack_category"},{"id":30906,"name":"miscellaneous","type":"techstack_category"},{"id":50906,"name":"social networks","type":"techstack_category"},{"id":5806,"name":"charting","type":"techstack_category"},{"id":36206,"name":"payment processing","type":"techstack_category"},{"id":12306,"name":"domain name services","type":"techstack_category"},{"id":47606,"name":"web servers","type":"techstack_category"},{"id":10006,"name":"data management","type":"techstack_category"},{"id":20506,"name":"font scripts","type":"techstack_category"},{"id":53406,"name":"wordpress plugins","type":"techstack_category"},{"id":45606,"name":"social media marketing software","type":"techstack_category"},{"id":1902,"name":"Mobile app","type":"technology"},{"id":209,"name":"Commission","type":"income_stream"},{"id":8806,"name":"content delivery network","type":"techstack_category"},{"id":34806,"name":"programming","type":"techstack_category"},{"id":17006,"name":"analytics","type":"techstack_category"},{"id":17606,"name":"enterprise mobility management","type":"techstack_category"},{"id":38206,"name":"payroll processing","type":"techstack_category"},{"id":5106,"name":"audio-video-graphics","type":"techstack_category"},{"id":43706,"name":"software framework","type":"techstack_category"}],"launch_date":"2016-01","closing_date":null,"employees_count":733,"added_at":"2016-09-23T08:33:20.000Z","updated_at":"2026-11-05T01:03:47.892Z","subtype":"company","classifications":["startup","thoroughbred","unicorn","vc_backed","funded"],"employee_count_1y_growth":31.362007,"status":"operational","signal_rating":96.64,"unicorn_type":"unicorn","became_unicorn_date":"2025-09","became_thoroughbred_date":"2024","exit_date":null,"investor":null,"funding":{"total":137605600,"total_vc":137605600,"rounds_count":6},"valuation":{"value":1000000000,"year":2025,"month":9},"jobs":{"is_hiring":true,"open_count":50},"founders":{"total":1,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":"Founder and Chief Executive Officer","titles":["CEO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"Barnaby Hussey-Yeo","type":"person","uuid":"8a9ee26e-0b84-4e66-bc26-30cc9c418b77","image":"storage.googleapis.com/dealroom-images-production/2024/12/12/e91c3629173a33319a58eed87a0d7f04.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/barnaby_hussey_yeo","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":400000000,"year":2026},"traffic":{"monthly_visits":590000,"growth_3m":-41},"available":["founders","revenue","traffic"]}', '2026-11-05T15:17:21.139Z', 'Cleo is an AI-powered financial assistant designed to help users, particularly Gen Z and millennials, manage their money through a conversational interface. The company was founded in 2016 by Barney Hussey-Yeo, a data scientist with a master''s degree in Machine Learning. Hussey-Yeo was motivated by his own struggles with money management and his experience at payday loan company Wonga, where he observed that customers were offered credit with little guidance on financial literacy. He began by creating scripts that would analyze his own banking and send him text alerts, an idea that evolved into Cleo. 

The company launched through the Entrepreneurs First accelerator program, initially as a chatbot on Facebook Messenger in the UK. After seeing rapid user adoption, Cleo entered the U.S. market in 2018 and shifted its focus entirely to this region. The platform operates on a freemium business model. The free version offers basic features like spending analysis, budget tracking, and bill reminders through its AI chatbot. Cleo''s AI communicates with a distinct, often humorous and sassy personality, offering features like "Roast Mode" to critique spending habits and "Hype Mode" to praise financial progress. 

Cleo generates revenue through tiered subscription plans that unlock advanced features. These premium tiers, such as Cleo Plus and Cleo Builder, provide services including interest-free cash advances up to $250, credit-building cards issued by WebBank, and enhanced financial insights. The Credit Builder Card is a secured card designed to help users establish or improve their credit scores. The company also earns interchange fees from transactions made with its card and fees from its cash advance service. Banking services are provided through a partnership with Thread Bank. 

Cleo has raised a total of approximately $175 million in funding over several rounds, with a Series C round of $80 million in 2022 led by Sofina. Other key investors include Balderton Capital, EQT Ventures, and LocalGlobe. The company was last valued at $500 million in 2022 and has demonstrated significant revenue growth, nearing profitability. Headquartered in London, Cleo has grown to a team of over 300 employees and has attracted millions of users, primarily in the United States. 

Keywords: AI financial assistant, personal finance, budgeting app, money management, chatbot, spending tracker, credit builder, cash advance, savings goals, fintech, Gen Z finance, financial health, AI money coach, expense tracking, overdraft protection, financial education, subscription model, transaction analysis, automated savings, credit score improvement', '["editors","project management","customer relationship management","human resources","web & portal technology","application development & management","javascript frameworks","intelligence and analytics","customer experience management","Artificial Intelligence","recruitment marketing","javascript graphics","data warehousing","error and exception monitoring","machine learning","source code management","continuous integration","human resource management system","content management system","SaaS","marketing automation","web tools and plugins","web analytics","Core AI","database","unified communications","containerization","ticket booking","certificates","document management systems","website builders","Mortgages & Lending","marketing analytics","dev tools","Venture Capital","uk is8 financial services","corporate learning management systems","Money Management","tag management","generative ai","content marketing","Challenger Bank","containers","software as a service","widgets","open source","infrastructure as a service","digital asset management","devops","Personal Finance","video players","communication and collaboration","a-b testing","financial inclusion","event management","e-commerce","pre-employment assessment","ui frameworks","design","operating systems & computing languages","platform as a service","fraud detection and prevention","business intelligence","it infrastructure","Machine Learning","Verified Unicorns and $1B Exits","business process management","retargeting","Banking","identity verification","real user monitoring","marketing performance measurement","advertising","personalization","email marketing","big data processing","security","Late stage","software development","Fintech","captcha","marketing","accounting","javascript libraries","advanced analytics and data science","visual and user generated content marketing","Verified Thoroughbreds","e-commerce platforms","message boards","accounting and finance","customer service","development","web fonts","loyalty and gamification","appointment scheduling","applicant tracking systems","caching","system analytics & monitoring","data management platforms","programming languages","governance-risk and compliance","cloud infrastructure computing","frameworks and libraries","performance","advertising networks","human capital management","augmented reality","affiliate advertising networks","live chat","online video platforms","human resource","deployment","cloud hosting","visualisation software","configuration management","payroll management and benefits administration","hris management","blogs","page builders","b2c","web hosting","team collaboration","web and application servers","Angel","uk is8 digital and technologies","file sharing","other advertising software","AI Applications","web platform extensions","tools","communications technology","web conferencing","Woman Founder","email","online community software","web frameworks","miscellaneous","social networks","charting","payment processing","domain name services","web servers","data management","font scripts","wordpress plugins","social media marketing software","Mobile app","Commission","content delivery network","programming","analytics","enterprise mobility management","payroll processing","audio-video-graphics","software framework"]', '["startup","thoroughbred","unicorn","vc_backed","funded"]', 96.64, 590000, 1, 50, 1000000000, -15500000, 2023, -22502524, 2022, '[{"year":2020,"revenue":4900000,"ebitda":-6899000,"profit":-8412017,"rnd":null,"valuation":264000000,"employees":null},{"year":2021,"revenue":11600000,"ebitda":-13173286,"profit":-15105038,"rnd":null,"va