INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('ad821ab6-7efa-4ad7-b5a7-4ba298464260', 'Modulr', 'modulrfinance.com', 'https://www.modulrfinance.com/', 'https://www.linkedin.com/company/modulr-finance/', 'https://app.dealroom.co/companies/modulr_finance', 'Providing embedded payment opportunities for every business', 'London', 'United Kingdom', 2015, 530, 18.568233, 191928077, 7, 55228822, 2025, 'operational', '[{"uuid":"c9175cc7-a44d-4479-b284-1fd58bfb4f00","name":"Nikolay Storonsky"},{"uuid":"5a6961ac-bce2-4ac3-99ed-679526145f96","name":"Martin Threakall"},{"uuid":"2c604238-53b9-4381-a170-1d8447b4a666","name":"Manoj Badale"},{"uuid":"78e52ba0-ffe8-43bc-ab73-c2a507a0d223","name":"Ritesh Tendulkar"},{"uuid":"d4c9d913-d840-4e85-86f6-a23a4533df71","name":"Ritesh Tendulkar"}]', '{"uuid":"ad821ab6-7efa-4ad7-b5a7-4ba298464260","type":"organization","domain":"modulrfinance.com","name":"Modulr","tagline":"Providing embedded payment opportunities for every business","about":"Modulr Finance is a fintech startup that offers a wide range of payment capabilities to businesses. The company operates in the financial services market, serving clients across various industries. Modulr''s business model is centered around simplifying and automating payment processes, enabling businesses to scale and improve operational efficiency. \n\nThe company offers a suite of services including automated payments, open banking technology, and the ability to generate physical and virtual cards. Their automated payment system allows businesses to set up ''if this, then that'' rules, enhancing efficiency and customer experience. The open banking technology helps protect businesses from fraud and enhances user experiences. The card generation service allows businesses to design and issue their own branded cards, offering greater flexibility to their teams and customers.\n\nModulr Finance is directly regulated by both the Financial Conduct Authority and De Nederlandsche Bank, ensuring a high level of compliance and security for its clients. The company also offers instant customer notifications, providing live updates on customer and business payments.\n\nModulr''s revenue model is based on partnerships and integrations. They partner with businesses to bring embedded payments to their customers, either through existing software or by enabling new products and services. They also offer the option for businesses to add Modulr directly to their platform, refer and revenue share, or even white label.\n\nIn summary, Modulr Finance is a fintech startup that provides a comprehensive suite of payment solutions, helping businesses to streamline their operations, protect against fraud, and create new revenue streams.\n\nKeywords: Fintech, Payment Solutions, Automated Payments, Open Banking, Card Generation, Compliance, Customer Notifications, Partnerships, Integrations, Revenue Sharing.","image":"storage.googleapis.com/dealroom-images-production/2026/10/26/f5cc186b94197192834182b7e498f7ec.png","dealroom_url":"https://app.dealroom.co/companies/modulr_finance","links":{"website":"https://www.modulrfinance.com/","linkedin":"https://www.linkedin.com/company/modulr-finance/","twitter":"https://twitter.com/modulrfinance","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/modulrfinance"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.493298,"lon":-0.224069},{"role":"founding","city":{"id":628061,"name":"