om-images-production/2025/04/25/423c23bc0244736db6d9997b2d5ef015.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/nikolay_storonsky","classifications":["serial_founder","super_founder"]}},{"raw_title":null,"titles":["COO","CPO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2015","end_date":null,"person":{"name":"Martin Threakall","type":"person","uuid":"5a6961ac-bce2-4ac3-99ed-679526145f96","image":"storage.googleapis.com/dealroom-images-production/2025/04/17/dbcbf557c5bc86e85f543047af861781.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/martin_threakall","classifications":["serial_founder","super_founder"]}},{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2015","end_date":null,"person":{"name":"Manoj Badale","type":"person","uuid":"2c604238-53b9-4381-a170-1d8447b4a666","image":"storage.googleapis.com/dealroom-images-production/2024/12/14/4fe4210e41142095685392942d85a443.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/manoj_badale_1","classifications":["serial_founder","super_founder"]}},{"raw_title":"Chief Innovation Officer, Co-founder","titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2015","end_date":null,"person":{"name":"Ritesh Tendulkar","type":"person","uuid":"78e52ba0-ffe8-43bc-ab73-c2a507a0d223","image":"storage.googleapis.com/dealroom-images-production/2023/07/20/e1e41dff33e2fbd81dc15bff811fe323.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/ritesh_tendulkar_1","classifications":["super_founder"]}},{"raw_title":null,"titles":["Chief Software Architect","CTO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2015","end_date":null,"person":{"name":"Ritesh Tendulkar","type":"person","uuid":"d4c9d913-d840-4e85-86f6-a23a4533df71","image":null,"subtype":null,"dealroom_url":"https://app.dealroom.co/people/ritesh_tendulkar","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":55228822,"year":2025},"traffic":{"monthly_visits":100000,"growth_3m":0},"available":["founders","revenue","traffic","portfolio","exits"]}', '2026-11-05T15:17:39.557Z', 'Modulr Finance is a fintech startup that offers a wide range of payment capabilities to businesses. The company operates in the financial services market, serving clients across various industries. Modulr''s business model is centered around simplifying and automating payment processes, enabling businesses to scale and improve operational efficiency. 

The company offers a suite of services including automated payments, open banking technology, and the ability to generate physical and virtual cards. Their automated payment system allows businesses to set up ''if this, then that'' rules, enhancing efficiency and customer experience. The open banking technology helps protect businesses from fraud and enhances user experiences. The card generation service allows businesses to design and issue their own branded cards, offering greater flexibility to their teams and customers.

Modulr Finance is directly regulated by both the Financial Conduct Authority and De Nederlandsche Bank, ensuring a high level of compliance and security for its clients. The company also offers instant customer notifications, providing live updates on customer and business payments.

Modulr''s revenue model is based on partnerships and integrations. They partner with businesses to bring embedded payments to their customers, either through existing software or by enabling new products and services. They also offer the option for businesses to add Modulr directly to their platform, refer and revenue share, or even white label.

In summary, Modulr Finance is a fintech startup that provides a comprehensive suite of payment solutions, helping businesses to streamline their operations, protect against fraud, and create new revenue streams.

