INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('c0bb1d08-86c6-4026-bd18-34ddb16d04d3', 'Raylo', 'raylo.com', 'https://www.raylo.com', 'https://www.linkedin.com/company/raylo/', 'https://app.dealroom.co/companies/raylo', 'Offering subscription-based access to electronics', 'London', 'United Kingdom', 2018, 144, 29.72973, 128254044, 8, 57000000, 2025, 'operational', '[{"uuid":"6f115e9b-42f9-4467-9033-6239a41078ee","name":"Filip Rybicki"},{"uuid":"8870d864-72d3-4b76-bf66-2964df37bb28","name":"Jinden Badesha"},{"uuid":"b1070f52-489a-417e-9080-e3bdd124619d","name":"Karl Gilbert"},{"uuid":"314f131e-cc2b-4a96-8e82-8d80084b867a","name":"Richard FultoN"}]', '{"uuid":"c0bb1d08-86c6-4026-bd18-34ddb16d04d3","type":"organization","domain":"raylo.com","name":"Raylo","tagline":"Offering subscription-based access to electronics","about":"Raylo is a tech startup operating in the device leasing market. It offers customers the opportunity to lease the latest devices starting from £7.99 per month, thereby reducing electronic waste. The company operates on a lease model where customers can apply for a new device of their choice at the end of their lease term without an upgrade fee. Alternatively, customers can continue to use their current device and continue paying monthly, or return the device and end their lease.\n\nRaylo serves a broad range of clients, from individuals seeking the latest tech without the upfront cost, to environmentally conscious consumers looking to reduce e-waste. The company makes money through the monthly lease payments from customers. \n\nThe company also places a strong emphasis on sustainability. Instead of discarded devices ending up in landfills, Raylo refurbishes and rehomes them with new customers. This, along with their use of plant-based packaging and electric vehicles, demonstrates their commitment to environmental responsibility.\n\nIn terms of customer service, Raylo offers flexibility. The lease begins when the device is shipped and the first payment is due 30 days later. If a customer changes their mind, they can cancel and return the device for free within the first 30 days. At the end of the lease, customers can upgrade for free and return their old device, or simply continue with their current device.\n\nKeywords: Device Leasing, Monthly Payments, Tech Startup, Electronic Waste Reduction, Sustainability, Refurbished Devices, Flexible Lease Terms, Free Upgrade, Environmentally Responsible, Customer Service.","image":"storage.googleapis.com/dealroom-images-production/2026/06/28/559d3b33e1b6c8fea4865c3965b44e27.png","dealroom_url":"https://app.dealroom.co/companies/raylo","links":{"website":"https://www.raylo.com","linkedin":"https://www.linkedin.com/company/raylo/","twitter":"https://twitter.com/raylo","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/raylo"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.515385,"lon":-0.1083333},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.5132,"lon":-0.1019604},{"role":"office","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.513245,"lon":-0.1018613}],"roles":[],"taxonomy":[{"id":14106,"name":"editors","type":"techstack_category"},{"id":23106,