INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('24d2db81-2fa5-4645-af69-b03bfb832c2e', 'RealityMine', 'realitymine.com', 'http://realitymine.com', 'https://www.linkedin.com/company/realitymine/', 'https://app.dealroom.co/companies/realitymine', 'Enables companies to analyse consumer behaviour by following them through their use of mobile devices', 'Gorse Hill', 'United Kingdom', 2012, 121, 47.560974, 20663000, 4, 2735906, 2017, 'operational', '[{"uuid":"5e5e77b1-4cfa-42cc-a659-e4dbf86b92f3","name":"Garry Partington"}]', '{"uuid":"24d2db81-2fa5-4645-af69-b03bfb832c2e","type":"organization","domain":"realitymine.com","name":"RealityMine","tagline":"Enables companies to analyse consumer behaviour by following them through their use of mobile devices","about":"RealityMine operates as a technology firm specializing in passive research into consumer behavior, with its headquarters in Manchester, England. The company was established in April 2012 by Garry Partington, a veteran in the mobile industry, and Rolfe Swinton, an expert in market research. Their goal was to address the significant gap in understanding what consumers actually do on their mobile devices. Garry Partington''s background includes a Bachelor of Science in Computer Science from Lancaster University and roles such as CEO of Panaram Ltd and CTO of EMCC Software, bringing extensive technology and mobile expertise to the venture. Prior to RealityMine, Rolfe Swinton had a background in market research. The company''s journey began with 5 employees in 2012, growing to 75 by 2015. A significant milestone was the acquisition of Media Behaviour Insights'' assets in December 2013, which included the USA TouchPoints brand. This acquisition integrated an e-diary mobile app for recording media behavior, enhancing RealityMine''s data collection capabilities. The company has secured a total of $20.7 million in funding over three rounds, including a Series B round of $17.2 million in December 2015. \n\n The core of RealityMine''s business is providing technology that enables market research and media organizations to monitor real consumers across multiple devices and platforms. This service provides clients, which include major global market research firms and brands in media, technology, and consumer goods, with unique insights derived from real-life consumer behavior. The business model centers on providing these technology solutions to partners who then use the collected data to generate insights for their end clients. RealityMine makes money by equipping these clients with its advanced passive metering solutions. Its services are live in numerous countries across five continents. \n\n RealityMine''s flagship product is the \"RealityMeter,\" a passive metering technology that can be deployed on Android, iOS, and desktop platforms. This software, installed with user permission, captures behavioral data such as websites visited, apps used, and in-app activity, including specific content consumed on streaming services. A key feature is its ability to provide a comprehensive view of digital device utilization by tracking web, search, streaming media, and app usage. In 2023, the company launched RealityMine Connect, a product that delivers verified, single-source, user-level measurement of streaming content consumption across all connected devices, including CTV. This addresses a critical gap for streaming platforms and studios by providing a complete understanding of audience behavior beyond first-party data. The platform is designed with a strong emphasis on privacy and is GDPR-compliant. It allows for granular analysis of the full-funnel shopping journey, from product discovery to checkout, and helps measure the impact of social media and advertising efforts. \n\n Keywords: consumer behavior analytics, passive data collection, market research technology, mobile usage tracking, digital behavior insights, cross-platform measurement, audience measurement, media consumption analysis, streaming analytics, shopper journey analysis, RealityMeter, behavioral data, advertising intelligence, competitive intelligence, consumer insights, user journey mapping, mobile market research, data collection software, app usage data, web browsing analysis","image":"storage.googleapis.com/dealroom-images-production/2026/10/26/c8027c88c5b137c61633ac03cbcdf5ff.png","dealroom_url":"https://app.dealroom.co/companies/realitymine","links":{"website":"http://realitymine.com","linkedin":"https://www.linkedin.com/company/realitymine/","twitter":"https://twitter.com/realityminetech","instagram":null,"angellist":"https://angel.co/realitymine","crunchbase":"https://www.crunchbase.com/organization/realitymine"},"locations":[{"role":"hq","city":{"id":1403101,"name":"Gorse Hill"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":53.467358,"lon":-2.3044486},{"role":"founding","city":{"id":1403101,"name":"Gorse Hill"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":53.467358,"lon":-2.3044486}],"roles":[],"taxonomy":[{"id":14106,"name":"editors","type":"techstack_category"},{"id":35406,"name":"project management","type":"techstack_category"},{"id":9406,"name":"customer relationship management","type":"techstack_category"},{"id":47806,"name":"web & portal technology","type":"techstack_category"},{"id":4406,"name":"application development & management","type":"techstack_category"},{"id":23806,"name":"javascript frameworks","type":"tech