INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at) VALUES ('ea85dca1-96db-4991-9528-86e2a5a0331c', 'Waracle', 'waracle.com', 'http://waracle.com', 'https://www.linkedin.com/company/waracle/', 'https://app.dealroom.co/companies/waracle', 'Enterprise mobile, web, and AI product development.', 'Dundee', 'United Kingdom', 2008, 380, 77.57009, 6350000, 1, 20228976, 2024, 'operational', '[{"uuid":"5fbf60d5-3575-461c-84df-bfcdc9275c98","name":"Michael Romilly"}]', '{"uuid":"ea85dca1-96db-4991-9528-86e2a5a0331c","type":"organization","domain":"waracle.com","name":"Waracle","tagline":"Enterprise mobile, web, and AI product development.","about":"Waracle is a technology services company specializing in the development of digital products, including mobile apps, web platforms, and AI-driven solutions. Founded in Dundee, Scotland, in 2007 as a spin-out from Abertay University by Michael Romilly, Mike Wharton, and David Romilly, the firm has grown from a small graduate startup into a company with over 330 employees across the UK and Europe. The company''s business model is centered on providing end-to-end digital product development for enterprise clients. This involves a collaborative process that spans from initial strategy and innovation to design, engineering, and ongoing optimization. Waracle operates by deploying dedicated teams of strategists, designers, engineers, and data scientists to work on client projects. Its primary revenue is generated through these service-based contracts with large organizations, focusing on delivering complex, regulated, and high-impact digital solutions. The company primarily serves clients in the financial services, digital health, energy, and public sectors. Waracle''s service offerings are structured around four main pillars: Strategy & Innovation, Data & Artificial Intelligence, Digital Product Development, and Platforms & Services. The company has a strong focus on mobile and web applications and has expanded its capabilities into AI, data science, cloud engineering, and DevOps. Recent strategic acquisitions, including Screenmedia, Hacksoft, and Inov8, have bolstered its expertise in these high-growth areas. Notable clients include Lloyds Banking Group, ScottishPower, Royal London, and Roche. David Tuck was appointed CEO in 2024, succeeding Chris Martin, with a mandate to accelerate growth and expand the company''s data and AI capabilities. The company continues to be headquartered in Dundee and has additional offices in London, Edinburgh, Glasgow, and Sofia, Bulgaria. Keywords: digital product development, mobile app development, artificial intelligence services, enterprise software, financial services technology, digital health solutions, energy sector technology, public sector digital services, user experience design, software engineering, cloud services, data engineering, technology consulting, agile development, digital transformation, platform optimization, DevOps, web applications, strategic innovation, regulatory technology","image":"storage.googleapis.com/dealroom-images-production/2025/10/07/f1b2bf00c0d0e5622bc624ab458fa03a.png","dealroom_url":"https://app.dealroom.co/companies/waracle","links":{"website":"http://waracle.com","linkedin":"https://www.linkedin.com/company/waracle/","twitter":"https://twitter.com/waracleuk","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/waracle"},"locations":[{"role":"hq","city":{"id":11231,"name":"Dundee"},"state":{"id":134922,"name":"Scotland"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":56